const LESSON_MODULES = [{"num": 1, "title": "Вычисления и преобразования выражений", "part": "Алгебра", "lessons": [{"num": 1, "title": "Действия с дробями. Порядок действий. Многоэтажные дроби", "short": "Дроби и многоэтажные дроби", "level": "base", "badge": "Базовый", "exam": "№2", "theory": {"rules": ["Десятичные дроби удобно переводить в обыкновенные: 0,2 = 1/5; 0,25 = 1/4; 1,125 = 9/8; 0,6 = 3/5.", "Смешанное число переводим в неправильную дробь: 1 3/4 = 7/4.", "<b>Многоэтажную дробь</b> считаем «снизу вверх»: сначала самый нижний этаж, затем поднимаемся.", "На экзамене Аничкова лицея калькулятор запрещён — ищите удобные сокращения до умножения."], "sample": "(2/7 − 0,2) · 1 3/4 = (10/35 − 7/35) · 7/4 = 3/35 · 7/4 = 3/20 = 0,15."}}, {"num": 2, "title": "Степени с натуральным показателем. Вычисления со степенями", "short": "Степени в вычислениях", "level": "base", "badge": "Базовый", "exam": "№2", "theory": {"rules": ["aᵐ · aⁿ = aᵐ⁺ⁿ;  aᵐ : aⁿ = aᵐ⁻ⁿ;  (aᵐ)ⁿ = aᵐⁿ;  (ab)ⁿ = aⁿbⁿ.", "Приводите степени к одному основанию: 25 = 5², 125 = 5³, 27 = 3³, 16 = 2⁴.", "В разности степеней выносите общий множитель: 5¹⁰ − 5⁹ = 5⁹ · (5 − 1).", "Разложите числа на простые множители: 392 = 2³ · 7², 18 = 2 · 3²."], "sample": "(25⁵ − 5⁹)/(125³) = (5¹⁰ − 5⁹)/(5⁹) = 5⁹ · 4 / 5⁹ = 4."}}, {"num": 3, "title": "Формулы сокращённого умножения в вычислениях", "short": "ФСУ в вычислениях", "level": "base", "badge": "Базовый", "exam": "№1", "theory": {"rules": ["(a + b)² = a² + 2ab + b²;  (a − b)² = a² − 2ab + b².", "a² − b² = (a − b)(a + b) — главная формула задания №1а.", "Квадраты чисел около 100: 101² = (100 + 1)² = 10201.", "Если видите a² ± 2ab + b² — свёрнутый квадрат!"], "sample": "89² − 91² = (89 − 91)(89 + 91) = (−2) · 180 = −360."}}, {"num": 4, "title": "Разложение на множители. Сокращение алгебраических дробей", "short": "Разложение и алгебраические дроби", "level": "adv", "badge": "Углублённый", "exam": "№1б, №3", "theory": {"rules": ["Способы разложения: вынесение общего множителя, группировка, ФСУ.", "4n² + 20n + 25 = (2n + 5)², поэтому m⁴ − (2n + 5)² = (m² − 2n − 5)(m² + 2n + 5).", "Сокращать можно только <b>множители</b>, а не слагаемые!", "Выражение не определено, если знаменатель (в том числе делителя) равен нулю."], "sample": "(9p² − 24pq + 16q²)/(9p² − 16q²) = (3p − 4q)²/((3p − 4q)(3p + 4q)) = (3p − 4q)/(3p + 4q)."}}]}, {"num": 2, "title": "Дроби, пропорции, проценты, смеси и сплавы", "part": "Алгебра", "lessons": [{"num": 5, "title": "Пропорции и проценты: число по проценту, изменение величины", "short": "Пропорции и проценты", "level": "base", "badge": "Базовый", "exam": "№1г", "theory": {"rules": ["p% от числа a: a · p/100. Если p% числа равны b, то число равно b · 100/p.", "Увеличить на p% — умножить на (1 + p/100); уменьшить — на (1 − p/100).", "Сколько процентов a составляет от b: a/b · 100%.", "Основное свойство пропорции a : b = c : d ⇔ ad = bc."], "sample": "Число увеличили на 24% и получили 93: x · 1,24 = 93, x = 75."}}, {"num": 6, "title": "Смеси, растворы, сплавы. Объединение совокупностей", "short": "Смеси и сплавы", "level": "adv", "badge": "Базовый + Михлин", "exam": "№5", "theory": {"rules": ["Масса вещества = масса смеси × концентрация.", "При добавлении воды масса вещества <b>не меняется</b>, меняется только масса смеси.", "При сушке не меняется масса <b>сухого вещества</b>.", "При объединении двух наборов складываем отдельно части и отдельно целые (метод Михлина: «таблица вещество/всего»)."], "sample": "1000 деталей (38% прямоуг.) + набор с 640 квадратными (20% прямоуг. ⇒ всего 800, прямоуг. 160): (380 + 160)/1800 = 30%."}}]}, {"num": 3, "title": "Степени и корни", "part": "Алгебра", "lessons": [{"num": 7, "title": "Степени с переменным и целым показателем", "short": "Степени с показателем n", "level": "adv", "badge": "Углублённый", "exam": "№1а, №2", "theory": {"rules": ["a⁰ = 1 (a ≠ 0);  a⁻ⁿ = 1/aⁿ.", "aⁿ⁺¹ · aⁿ⁻³ = a²ⁿ⁻²; 25ⁿ = 5²ⁿ; (−14)²ⁿ = 196ⁿ = 4ⁿ · 49ⁿ.", "Выражения с n обычно «сокращаются» до числа — ответ не зависит от n.", "Из суммы степеней выносим за скобку меньшую: 49ⁿ⁺¹ − 7²ⁿ⁺¹ = 49ⁿ · (49 − 7)."], "sample": "(5ⁿ⁺¹ · 5ⁿ⁻³) : 25ⁿ = 5²ⁿ⁻² : 5²ⁿ = 5⁻² = 1/25."}}, {"num": 8, "title": "Арифметический квадратный корень и его свойства", "short": "Квадратный корень", "level": "adv", "badge": "Углублённый · 8 кл.", "exam": "", "theory": {"rules": ["√a — неотрицательное число, квадрат которого равен a (a ≥ 0).", "√(ab) = √a · √b;  √(a/b) = √a : √b;  (√a)² = a.", "√(a²) = |a| — частая ловушка!", "Для оценки корня ищите соседние полные квадраты: 49 < 50 < 64 ⇒ 7 < √50 < 8."], "sample": "√((3 − √10)²) = |3 − √10| = √10 − 3, так как √10 > 3."}}]}, {"num": 4, "title": "Уравнения и системы уравнений", "part": "Алгебра", "lessons": [{"num": 9, "title": "Линейные уравнения. Уравнения с дробями и ФСУ", "short": "Линейные уравнения", "level": "base", "badge": "Базовый", "exam": "№3", "theory": {"rules": ["Переносим слагаемые с x влево, числа — вправо, меняя знак.", "Дробные коэффициенты: умножьте обе части на общий знаменатель.", "ax = b: при a ≠ 0 один корень; при a = 0, b ≠ 0 — нет корней; при a = b = 0 — бесконечно много.", "Если в уравнении есть квадраты, раскройте их по ФСУ — x² часто сокращается."], "sample": "(x − 2)² + 3(x − 1)² = (2x − 5)²  ⇒  4x² − 10x + 7 = 4x² − 20x + 25  ⇒  10x = 18, x = 1,8."}}, {"num": 10, "title": "Уравнения «произведение = 0». Дробные уравнения и ОДЗ", "short": "Произведение = 0 и ОДЗ", "level": "adv", "badge": "Углублённый", "exam": "№3", "theory": {"rules": ["Произведение равно нулю ⇔ хотя бы один множитель равен нулю (а остальные имеют смысл).", "Не делите обе части на выражение с x — потеряете корень! Переносите всё влево и выносите общий множитель.", "<b>ОДЗ:</b> знаменатель ≠ 0. Найденные корни обязательно проверяйте — это любимая ловушка лицея.", "Дроби вида (a² − 2ab + b²)/(a − b) сокращаются до (a − b) при a ≠ b."], "sample": "(x − 2)(x² + 5x + 6) = (2x − 4)(x² + 3x + 3) ⇒ (x − 2)(−x² − x) = 0 ⇒ x = 2; 0; −1."}}, {"num": 11, "title": "Системы линейных уравнений. Задачи, решаемые системой", "short": "Системы уравнений", "level": "base", "badge": "Базовый", "exam": "№1в", "theory": {"rules": ["<b>Способ сложения:</b> складываем/вычитаем уравнения, чтобы одна переменная исчезла.", "<b>Способ подстановки:</b> выражаем одну переменную и подставляем в другое уравнение.", "Симметричные системы (2x + 3y, 3x + 2y): сложите и вычтите уравнения — получите x + y и x − y.", "Ответ к системе — пара чисел (x; y)."], "sample": "2x + 3y = 7, 3x + 2y = 3: сумма 5(x + y) = 10 ⇒ x + y = 2; разность x − y = −4 ⇒ x = −1, y = 3."}}, {"num": 12, "title": "Квадратные уравнения. Теорема Виета", "short": "Квадратные уравнения", "level": "adv", "badge": "Углублённый · 8 кл.", "exam": "", "theory": {"rules": ["ax² + bx + c = 0, D = b² − 4ac. При D > 0 два корня, D = 0 — один, D < 0 — корней нет.", "x = (−b ± √D)/(2a).", "<b>Виет:</b> x₁ + x₂ = −b/a, x₁ · x₂ = c/a.", "Неполные уравнения решаем без дискриминанта: вынесением x или переносом числа."], "sample": "2x² + 3x − 2 = 0: D = 9 + 16 = 25, x = (−3 ± 5)/4 ⇒ x = 0,5; −2."}}]}, {"num": 5, "title": "Неравенства, модуль, метод интервалов", "part": "Алгебра", "lessons": [{"num": 13, "title": "Линейные неравенства. Уравнения и неравенства с модулем", "short": "Неравенства и модуль", "level": "adv", "badge": "Базовый + углублённый", "exam": "", "theory": {"rules": ["При умножении или делении неравенства на отрицательное число знак меняется на противоположный.", "|a| — расстояние от a до 0 на числовой прямой; |x − a| — расстояние от x до a.", "|x − a| = b (b ≥ 0) ⇔ x = a ± b;  |x − a| ≤ b ⇔ a − b ≤ x ≤ a + b.", "|x − a| + |x − b| = |a − b| выполняется для всех x между a и b."], "sample": "|x − 2| ≤ 3 ⇔ −1 ≤ x ≤ 5 — это 7 целых чисел."}}, {"num": 14, "title": "Метод интервалов. Квадратные и дробные неравенства", "short": "Метод интервалов", "level": "adv", "badge": "Углублённый · 8–9 кл.", "exam": "", "theory": {"rules": ["Найдите нули всех множителей (и знаменателя), отметьте их на прямой.", "Определите знак на крайнем правом промежутке и чередуйте знаки (если множители в первой степени).", "Нули знаменателя всегда «выколоты»; нули числителя закрашены при нестрогом знаке.", "x² − a² > 0 ⇔ x < −a или x > a."], "sample": "(x − 4)/(x + 2) ≥ 0: нули 4 и −2; ответ x < −2 или x ≥ 4."}}]}, {"num": 6, "title": "Текстовые задачи: движение, работа, среднее", "part": "Алгебра", "lessons": [{"num": 15, "title": "Задачи на движение: навстречу, вдогонку, по реке, по кругу", "short": "Задачи на движение", "level": "base", "badge": "Базовый + Михлин", "exam": "№5", "theory": {"rules": ["S = v · t. Навстречу: скорость сближения v₁ + v₂. Вдогонку: v₁ − v₂.", "По реке: v по теч. = v соб. + v теч.;  v против теч. = v соб. − v теч.", "По кругу в одном направлении первый догоняет второго, пробежав на целый круг больше.", "Составляйте таблицу «скорость — время — путь» для каждого участника."], "sample": "Эрвин полз 15 м/мин, плыл 50 м/мин, всего 5 мин, проплыл на 55 м больше: 50(5 − t) − 15t = 55 ⇒ t = 3."}}, {"num": 16, "title": "Задачи на работу, среднее арифметическое и изменение величин", "short": "Работа и среднее", "level": "base", "badge": "Базовый + Михлин", "exam": "№1е, №5", "theory": {"rules": ["Вся работа = 1. Производительность = 1 : время. При совместной работе производительности складываются.", "Среднее арифметическое = сумма : количество. Сумма = среднее × количество.", "Если величина меняется на одно и то же число за каждый промежуток, после k промежутков: a + k · d.", "Время в задачах про часы удобно переводить в минуты."], "sample": "Средний возраст 11 футболистов 22 года: сумма 242. Без 32-летнего: (242 − 32) : 10 = 21."}}]}, {"num": 7, "title": "Функции и графики", "part": "Алгебра", "lessons": [{"num": 17, "title": "Линейная функция y = kx + b: график, параллельность, пересечение", "short": "Линейная функция", "level": "base", "badge": "Базовый", "exam": "№4", "theory": {"rules": ["k — угловой коэффициент, b — ордината точки пересечения с осью Oy.", "Прямые y = k₁x + b₁ и y = k₂x + b₂ параллельны ⇔ k₁ = k₂, b₁ ≠ b₂ (не пересекаются).", "Точка (x₀; y₀) лежит на графике ⇔ y₀ = kx₀ + b.", "Точка пересечения прямых — решение системы из их уравнений; с осью Ox — при y = 0."], "sample": "Прямая через A(−1; −1) и B(1; 5): k = (5 − (−1))/(1 − (−1)) = 3, b = 5 − 3 = 2 ⇒ y = 3x + 2."}}, {"num": 18, "title": "Квадратичная функция, гипербола, функция с модулем", "short": "Парабола, гипербола, |x|", "level": "adv", "badge": "Углублённый · 8–9 кл.", "exam": "", "theory": {"rules": ["y = ax² + bx + c — парабола; вершина при x₀ = −b/(2a); при a > 0 ветви вверх.", "y = k/x — гипербола; при k > 0 ветви в I и III четвертях, при k < 0 — во II и IV.", "y = |x − a| + b — «галочка» с вершиной (a; b); наименьшее значение равно b.", "Нули функции — точки пересечения графика с осью Ox."], "sample": "y = x² − 4x + 3: x₀ = 2, y₀ = 4 − 8 + 3 = −1; вершина (2; −1); нули 1 и 3."}}]}, {"num": 8, "title": "Последовательности и прогрессии", "part": "Алгебра", "lessons": [{"num": 19, "title": "Арифметическая и геометрическая прогрессии", "short": "Прогрессии", "level": "adv", "badge": "Углублённый · 9 кл.", "exam": "", "theory": {"rules": ["Арифметическая: aₙ = a₁ + (n − 1)d;  Sₙ = (a₁ + aₙ) · n / 2.", "Геометрическая: bₙ = b₁ · qⁿ⁻¹;  Sₙ = b₁(qⁿ − 1)/(q − 1).", "Сумма 1 + 2 + … + n = n(n + 1)/2 (приём Гаусса).", "Сумма первых n нечётных чисел равна n²."], "sample": "1 + 2 + … + 100 = (1 + 100) · 100 / 2 = 5050."}}]}, {"num": 9, "title": "Логика, делимость и олимпиадные методы", "part": "Алгебра", "lessons": [{"num": 20, "title": "Делимость и подсчёт: «каждый третий», включения-исключения", "short": "Делимость и подсчёт", "level": "oly", "badge": "Олимпиадный", "exam": "№7", "theory": {"rules": ["Чисел от 1 до N, делящихся на k: [N/k] (целая часть).", "Делящихся и на a, и на b (взаимно простые): [N/(ab)].", "Формула включений-исключений: |A ∪ B| = |A| + |B| − |A ∩ B|.", "Признаки делимости на 3 и 9 — по сумме цифр; число делителей n = p₁ᵃ·p₂ᵇ равно (a + 1)(b + 1)."], "sample": "980 карточек: водных [980/3] = 326, летающих [980/5] = 196, обоих [980/15] = 65. Ни тех ни других: 980 − (326 + 196 − 65) = 523."}}, {"num": 21, "title": "Логические задачи, рыцари и лжецы, взвешивания, часы", "short": "Логика и часы", "level": "oly", "badge": "Олимпиадный", "exam": "№7", "theory": {"rules": ["Логические таблицы: ставьте «+» и «−» и исключайте варианты.", "Рыцарь всегда говорит правду, лжец всегда лжёт. Ищите противоречие в предположении.", "Взвешивания: за k взвешиваний можно найти лёгкую монету среди 3ᵏ монет.", "Часы, отстающие на 6 мин в час, за реальный час проходят 54 мин."], "sample": "Глип, Влип и Блип: Блип — сундучок, не лимон и не абрикос (под абрикосом мешочек) ⇒ банан. Ракушка не у Глипа ⇒ у Влипа, Глипу — мешочек и абрикос."}}, {"num": 22, "title": "Принцип Дирихле, чётность, инварианты, остатки", "short": "Дирихле и инварианты", "level": "oly", "badge": "Олимпиадный", "exam": "№7", "theory": {"rules": ["<b>Принцип Дирихле:</b> если n кроликов сидят в k клетках, то в какой-то клетке не меньше ⌈n/k⌉ кроликов.", "Сумма нечётного количества нечётных чисел нечётна; чётного — чётна.", "<b>Инвариант</b> — величина, не меняющаяся при разрешённых операциях (например, чётность суммы).", "Число нулей в конце n! равно числу множителей 5: [n/5] + [n/25] + …"], "sample": "Можно ли разменять 25 р. десятью монетами по 1, 3, 5 р.? Сумма десяти нечётных чисел чётна ≠ 25 ⇒ нельзя."}}, {"num": 23, "title": "Комбинаторика: правило произведения, перестановки, выборы", "short": "Комбинаторика", "level": "oly", "badge": "Олимпиадный", "exam": "", "theory": {"rules": ["<b>Правило произведения:</b> если первый выбор — m способов, второй — n, то вместе m · n.", "Перестановки n предметов: n! = 1 · 2 · … · n.", "Выбрать 2 из n (порядок не важен): n(n − 1)/2. Порядок важен: n(n − 1).", "Диагоналей у n-угольника: n(n − 3)/2."], "sample": "Трёхзначные числа из цифр 1–4 с повторениями: 4 · 4 · 4 = 64; без повторений: 4 · 3 · 2 = 24."}}]}, {"num": 10, "title": "Треугольники", "part": "Геометрия", "lessons": [{"num": 24, "title": "Углы. Параллельные прямые. Сумма углов треугольника, внешний угол", "short": "Углы и сумма углов", "level": "base", "badge": "Базовый", "exam": "№1д, №6", "theory": {"rules": ["Смежные углы в сумме дают 180°, вертикальные углы равны.", "При параллельных прямых: накрест лежащие и соответственные углы равны, односторонние в сумме 180°.", "Сумма углов треугольника 180°. Внешний угол равен сумме двух внутренних, не смежных с ним.", "Угол между высотой и биссектрисой из вершины B равен |∠A − ∠C| / 2."], "sample": "∠A = 23°, ∠C = 39°: ∠B = 118°, ∠ABL = 59°, ∠ABD = 90° − 23° = 67°, ∠DBL = 67° − 59° = 8°."}}, {"num": 25, "title": "Равнобедренный и прямоугольный треугольник. Катет против 30°", "short": "Прямоугольный треугольник", "level": "base", "badge": "Базовый", "exam": "№6", "theory": {"rules": ["В равнобедренном треугольнике углы при основании равны; медиана к основанию — и биссектриса, и высота.", "Катет, лежащий против угла 30°, равен половине гипотенузы.", "Медиана, проведённая к гипотенузе, равна половине гипотенузы (M — центр описанной окружности).", "Если в треугольнике два угла равны — он равнобедренный (ищите такие треугольники на чертеже!)."], "sample": "∠C = 90°, CM = 7 — медиана, AB = 14, ∠CMB = 120°: ∠AMC = 60°, AM = MC ⇒ △AMC равносторонний ⇒ ∠A = 60°, AC = 7."}}, {"num": 26, "title": "Признаки равенства. Неравенство треугольника. Отрезки и медианы", "short": "Равенство и неравенство", "level": "base", "badge": "Базовый", "exam": "№1е, №6", "theory": {"rules": ["I признак: две стороны и угол между ними; II: сторона и два прилежащих угла; III: три стороны.", "Неравенство треугольника: каждая сторона меньше суммы двух других.", "Угол против большей стороны больше. Тупой угол ⇒ противолежащая сторона: c² > a² + b².", "Середины отрезков: расстояние между серединами AD и DC равно AC / 2."], "sample": "Стороны при тупом угле 4 и 7: третья сторона c > √(16 + 49) ≈ 8,06 и c < 11 ⇒ c = 9 или 10."}}, {"num": 27, "title": "Теорема Пифагора и подобие треугольников", "short": "Пифагор и подобие", "level": "adv", "badge": "Углублённый · 8 кл.", "exam": "", "theory": {"rules": ["Теорема Пифагора: c² = a² + b². Пифагоровы тройки: 3-4-5, 5-12-13, 8-15-17.", "Подобные треугольники: стороны пропорциональны с коэффициентом k, периметры относятся как k, площади — как k².", "Прямая, параллельная стороне, отсекает треугольник, подобный исходному.", "Высота к гипотенузе: h = ab / c."], "sample": "Катеты 6 и 8: гипотенуза 10, высота к гипотенузе 6 · 8 / 10 = 4,8."}}]}, {"num": 11, "title": "Четырёхугольники", "part": "Геометрия", "lessons": [{"num": 28, "title": "Параллелограмм, ромб, прямоугольник, трапеция", "short": "Четырёхугольники", "level": "adv", "badge": "Углублённый · 8 кл.", "exam": "№6", "theory": {"rules": ["Параллелограмм: противоположные стороны и углы равны, соседние углы в сумме 180°, диагонали делятся пополам.", "Ромб: диагонали перпендикулярны и являются биссектрисами. Прямоугольник: диагонали равны.", "Средняя линия трапеции равна полусумме оснований.", "Биссектриса угла параллелограмма отсекает равнобедренный треугольник."], "sample": "ABCD: AB = BC = CD, ∠B = ∠C = 120°, AC = 7, ∠CAD = 30° ⇒ ∠ACD = 90°, ∠D = 60°, BD = AC = 7, CH = AC/2 = 3,5."}}]}, {"num": 12, "title": "Окружность", "part": "Геометрия", "lessons": [{"num": 29, "title": "Вписанные углы, хорды, касательные, вписанные и описанные фигуры", "short": "Окружность", "level": "adv", "badge": "Углублённый · 8 кл.", "exam": "", "theory": {"rules": ["Вписанный угол равен половине центрального, опирающегося на ту же дугу; опирающийся на диаметр — 90°.", "Касательная перпендикулярна радиусу; отрезки касательных из одной точки равны.", "Во вписанном четырёхугольнике сумма противоположных углов 180°; в описанном — суммы противоположных сторон равны.", "Центр окружности, описанной около прямоугольного треугольника, — середина гипотенузы."], "sample": "Хорда 16, радиус 10: расстояние от центра √(10² − 8²) = 6."}}]}, {"num": 13, "title": "Площади и отношения площадей", "part": "Геометрия", "lessons": [{"num": 30, "title": "Площади многоугольников. Отношения площадей", "short": "Площади", "level": "adv", "badge": "Углублённый · 8 кл.", "exam": "", "theory": {"rules": ["S треуг. = ½ · a · h;  S паралл. = a · h = a · b · sin α;  S ромба = ½ · d₁ · d₂;  S трапеции = (a + b)/2 · h.", "Треугольники с общей высотой: площади относятся как основания.", "Медиана делит треугольник на два равновеликих.", "Средняя линия отсекает треугольник с площадью ¼ исходной."], "sample": "D на AC, AD : DC = 2 : 3, S(ABC) = 40 ⇒ S(ABD) = 40 · 2/5 = 16."}}]}, {"num": 14, "title": "Координатный метод и векторы", "part": "Геометрия", "lessons": [{"num": 31, "title": "Координаты на плоскости. Середина отрезка, расстояние, векторы", "short": "Координаты и векторы", "level": "adv", "badge": "Углублённый · 8–9 кл.", "exam": "№4", "theory": {"rules": ["Середина отрезка: ((x₁ + x₂)/2; (y₁ + y₂)/2).", "Расстояние: AB = √((x₂ − x₁)² + (y₂ − y₁)²).", "Вектор AB = (x₂ − x₁; y₂ − y₁); длина |(a; b)| = √(a² + b²).", "ABCD — параллелограмм ⇔ AB = DC (как векторы) ⇔ D = A + C − B."], "sample": "A(−2; −1), B(1; 3), C(5; 3): D = A + C − B = (−2 + 5 − 1; −1 + 3 − 3) = (2; −1)."}}]}, {"num": 15, "title": "Построения, клетчатая бумага, разрезания", "part": "Геометрия", "lessons": [{"num": 32, "title": "Задачи на клетчатой бумаге, построения и разрезания", "short": "Клетчатая бумага и разрезания", "level": "oly", "badge": "Олимпиадный", "exam": "№6, №7", "theory": {"rules": ["Площадь фигуры на клетчатой бумаге: достройте до прямоугольника и вычтите лишние прямоугольные треугольники.", "Формула Пика: S = В + Г/2 − 1 (В — узлы внутри, Г — узлы на границе).", "Поворот вектора (a; b) на 90°: (−b; a) или (b; −a).", "Раскраска в шахматном порядке — главный инструмент в задачах «можно ли разрезать»."], "sample": "Доска 8×8 без двух противоположных угловых клеток: убраны две клетки одного цвета, а каждая доминошка покрывает две клетки разного цвета ⇒ нельзя."}}]}, {"num": 16, "title": "Пробный экзамен в формате Аничкова лицея", "part": "Экзамен", "lessons": [{"num": 33, "title": "Пробный вариант: 7 заданий в формате вступительного экзамена", "short": "Пробный экзамен", "level": "oly", "badge": "Формат экзамена", "exam": "№1–7", "theory": {"rules": ["Структура работы (2016–2026): 1 — «математическая база», 2 — вычисления, 3 — уравнения, 4 — линейная функция, 5 — текстовая задача, 6 — геометрия, 7 — нестандартная задача.", "Калькулятором пользоваться нельзя. На экзамене нужно записать полное решение — в тренажёре вводим только ответы.", "Рекомендуемое время на пробный вариант: 90–120 минут.", "Проверяйте ОДЗ в уравнениях и единицы измерения в текстовых задачах."], "sample": "Пробный вариант составлен по типам заданий 2016–2026 гг. (архив spbal.ru)."}}]}];
